SourceCode.Declaration:
/// <summary>
/// Extension of class <c>SalesInvoiceDP</c>
/// </summary>
[ExtensionOf(classStr(SalesInvoiceDP))]
final class KPMGSalesInvoiceDP_Extension
{


}

Method.Source:
    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_companyInfo">_companyInfo</param>
    protected void populateSalesInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
    {
       
        next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);
        
        SalesTable  salesTable;
        MarkupTrans markupTrans,markupTransBuf;
        CustInvoiceJour custInvoiceJourBuf;
        TaxTrans taxTransBuf;
        #define.Admin('Admin')

        salesTable = SalesTable::find(salesInvoiceHeaderFooterTmp.SalesId);
        salesInvoiceHeaderFooterTmp.KPMGDeliveryName        = salesTable.DeliveryName;
        salesInvoiceHeaderFooterTmp.KPMGDeliveryAddress     = salesTable.deliveryAddressing();
        salesInvoiceHeaderFooterTmp.KPMGDeliveryDate        = salesTable.DeliveryDate;
        salesInvoiceHeaderFooterTmp.KPMGOrderDiscount       = salesTable.DiscPercent;
        salesInvoiceHeaderFooterTmp.KPMGCashDiscDesc        = CashDisc::find(salesTable.CashDisc).Description;
        salesInvoiceHeaderFooterTmp.KPMGPurchOrderFormNum   = salesTable.PurchOrderFormNum;
        
        Map         metChargesMap = new Map(Types::String, Types::Real);
        boolean     isReturnOrder = salesTable.SalesType == SalesType::ReturnItem;
        boolean isALMReport;
        if (METSalesOrderTypes::find(salesTable.METSalesOrderType).SalesInvoiceReportDesignName == METConstants::ALMDirectsCTInvoice)
        {
            isALMReport = NoYes::Yes;
        }
        
        //updated code to group based on the code and sum the values.
        while select MarkupCode, CalculatedAmount,MarkupCategory, Value from markupTrans// group by markupTrans.MarkupCode, markupTrans.Value, markupTrans.MarkupCategory
            where markupTrans.TransTableId == _custInvoiceJour.TableId
            && markupTrans.TransRecId == _custInvoiceJour.RecId
            && markupTrans.CalculatedAmount != 0
        {
            // Lasernet change request - show all markups including
            if (markupTrans.MarkupCategory == MarkupCategory::Fixed)
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges  += markupTrans.MarkupCode  + ' ' + METConstants::Dollar  +  num2Str(markupTrans.Value, 1,2, 1,0) + '\n';
               
            }
            else if (markupTrans.MarkupCategory == MarkupCategory::Percent)
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges  += markupTrans.MarkupCode  +  ' ' +  num2Str(markupTrans.Value, 1,2, 1,0) +  METConstants::Percent + '\n';
            }
            else
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges  += markupTrans.MarkupCode +  ' ' +  num2Str(markupTrans.Value, 1,2, 1,0) + '\n';
            }
          
            if (markupTrans.MarkupCode == #Admin)
            {
                salesInvoiceHeaderFooterTmp.METAdminFeeSymbol = (markupTrans.MarkupCategory == MarkupCategory::Fixed) ? METConstants::Dollar : METConstants::Percent;
            }
            //total price incl gst

            //<Bug 288553: CB272 - MFG/CSD/ALM Invoicing - GST Values to be displayed for Fees and Invoice Totals on INV>
            select sum(SourceTaxAmountCur) from taxTransBuf
                where markupTrans.RecId == taxTransBuf.SourceRecId && markupTrans.TableId == taxTransBuf.SourceTableId
                 && taxTransBuf.SourceTaxAmountCur != 0;

            if (taxTransBuf.SourceTaxAmountCur)
            {
                Amount  gstExclValue;
                
                if (isALMReport && isReturnOrder)
                {
                    gstExclValue                                        = abs(markupTrans.CalculatedAmount) + abs(taxTransBuf.SourceTaxAmountCur);
                    salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue  += strFmt('%1', abs(gstExclValue)) + '\n';
                    salesInvoiceHeaderFooterTmp.METHeaderLineGSTValue   += strFmt('%1',abs(taxTransBuf.SourceTaxAmountCur)) + '\n';//GST
                }
                else
                {
                    gstExclValue                                        = markupTrans.CalculatedAmount + taxTransBuf.SourceTaxAmountCur;
                    salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue  += strFmt('%1', gstExclValue) + '\n';
                    salesInvoiceHeaderFooterTmp.METHeaderLineGSTValue   += strFmt('%1',taxTransBuf.SourceTaxAmountCur) + '\n';//GST
                }
                
                salesInvoiceHeaderFooterTmp.METHeaderLineTotExclGSTValue    += strFmt('%1',markupTrans.CalculatedAmount) + '\n';
            }
            else
            {
                salesInvoiceHeaderFooterTmp.METHeaderLineGSTValue += strFmt('%1', 0) + '\n';
                salesInvoiceHeaderFooterTmp.METHeaderLineTotExclGSTValue  += strFmt('%1',0) + '\n';

                // For return sales type, the value should be shown as negative in invoice.
                salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue          += strFmt('%1',markupTrans.CalculatedAmount) + '\n';

            }
            //</Bug 288553>
        }
        /*
            if(metChargesMap.exists(markupTrans.Txt))
            {
                Bug 237683
                metChargesMap.insert(markupTrans.Txt, metChargesMap.lookup(markupTrans.Txt) + markupTrans.CalculatedAmount);
            }
            else
            {
                metChargesMap.insert(markupTrans.Txt, markupTrans.CalculatedAmount);
            }
            CB272- instead of flag we have added a enum field to identoy the charge type.
            if(markupTrans.markupTable().METChargeType == METChargeType::DeliveryFees)
            {
                salesInvoiceHeaderFooterTmp.METDeliveryFee += markupTrans.Value;
            }
            if(markupTrans.markupTable().METChargeType  == METChargeType::AdminFees)
            {
                salesInvoiceHeaderFooterTmp.METAdminFee += markupTrans.Value;
            }
        }
        
        //MPJ_31513 Invoicing Design Begin

        markupTrans metMarkupTransInvoiceStd;
        CustInvoiceTrans metCustInvoiceTransInvoiceStd;
        while select sum(CalculatedAmount) from metMarkupTransInvoiceStd
            group by txt
           exists join metCustInvoiceTransInvoiceStd
            where metCustInvoiceTransInvoiceStd.TableId  == metMarkupTransInvoiceStd.TransTableId &&
                  metCustInvoiceTransInvoiceStd.RecId == metMarkupTransInvoiceStd.TransRecId  &&
                  metCustInvoiceTransInvoiceStd.InvoiceId == _custInvoiceJour.InvoiceId
        {
            if(metChargesMap.exists(metMarkupTransInvoiceStd.Txt))
            {
                metChargesMap.insert(metMarkupTransInvoiceStd.Txt,
                                metChargesMap.lookup(metMarkupTransInvoiceStd.Txt) + metMarkupTransInvoiceStd.CalculatedAmount);
            }
            else
            {
                metChargesMap.insert(metMarkupTransInvoiceStd.Txt, metMarkupTransInvoiceStd.CalculatedAmount);
            }

        }
         Fee totals
        MapEnumerator       metMapEnumeratorStd;
        metMapEnumeratorStd = metChargesMap.getEnumerator();
        while (metMapEnumeratorStd.moveNext())
        {
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesCode    += metMapEnumeratorStd.currentKey() + '\n';
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesValue   += strFmt('%1',metMapEnumeratorStd.currentValue()) + '\n';
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesTotal   +=metMapEnumeratorStd.currentValue();
        } */

        CompanyInfo         companyInfo = CompanyInfo::find();
        CustInvoiceTrans    metCustInvoiceTransStd;
        InventDim           metInventDimStd;

        select firstonly inventSiteId, InventLocationId from metInventDimStd
            exists join metCustInvoiceTransStd
                where metCustInvoiceTransStd.inventDimId == metInventDimStd.inventDimId && metCustInvoiceTransStd.ParentRecId == _custInvoiceJour.RecId;

        salesInvoiceHeaderFooterTmp.METBranchNumber             = metInventDimStd.InventLocationId;
        salesInvoiceHeaderFooterTmp.METBranchName               = InventLocation::find(metInventDimStd.InventLocationId).Name;
        //LogisticsPostalAddress metLogisticsPostalAddressStd     = LogisticsPostalAddress::findByLocation(InventLocation::getLocationFromRole(InventLocation::find(metInventDimStd.InventLocationId).RecId, LogisticsLocationRoleType::Delivery));
        //salesInvoiceHeaderFooterTmp.METSupplierSiteNameAddress  = metLogisticsPostalAddressStd.Address;
        
        CustTable custTableloc = Custtable::find(salesTable.InvoiceAccount);
        LogisticsElectronicAddress logisticsElectronicAddressloc;
        DirPartyLocation dirPartyLocationloc;
        
        //salesInvoiceHeaderFooterTmp.METInvoiceToPhone = logisticsElectronicAddressloc.Locator;
        CustTable                           cuttable;
        DirPartyLocation                    dirPartyLocation;
        LogisticsElectronicAddress          logisticsElectronicAddress;
        LogisticsElectronicAddressRole      logisticsElectronicAddressRole;
        LogisticsLocationRole               logisticsLocationRole;
   
        select firstonly logisticsElectronicAddress
            where logisticsElectronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
            exists join dirPartyLocation
                where dirPartyLocation.Location == logisticsElectronicAddress.Location &&
                    dirPartyLocation.Party == custTableloc.Party
            exists join logisticsElectronicAddressRole
                where logisticsElectronicAddressRole.ElectronicAddress == logisticsElectronicAddress.RecId
            exists join logisticsLocationRole
                where logisticsLocationRole.RecId == logisticsElectronicAddressRole.LocationRole
                && logisticsLocationRole.Name == strFmt("%1",logisticsLocationRoleType::Invoice);

        salesInvoiceHeaderFooterTmp.MetInvoiceToPhone = logisticsElectronicAddress.Locator;
       
        //get delivery phone number of customer.
        select firstonly logisticsElectronicAddress
            where logisticsElectronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
            exists join dirPartyLocation
                where dirPartyLocation.Location == logisticsElectronicAddress.Location&&
                    dirPartyLocation.Party == custTableloc.Party
            exists join logisticsElectronicAddressRole
                where logisticsElectronicAddressRole.ElectronicAddress == logisticsElectronicAddress.RecId
            exists join logisticsLocationRole
                where logisticsLocationRole.RecId == logisticsElectronicAddressRole.LocationRole
                && logisticsLocationRole.Name == strFmt("%1",logisticsLocationRoleType::Delivery);

        salesInvoiceHeaderFooterTmp.METShipToPhone          = logisticsElectronicAddress.Locator;//salesTable.deliveryPhone();
        //MPJ_31513 Invoicing Design End

        //Fees logic
        MarkupTrans markupTransHeaderFees;

        select sum(CalculatedAmount) from markupTransHeaderFees
            where markupTransHeaderFees.TransTableId == _custInvoiceJour.TableId
            && markupTransHeaderFees.TransRecId == _custInvoiceJour.RecId;

        METInvoiceTypeSO chargeThroughType = salesTable.METInvoiceType;

        if (chargeThroughType == METInvoiceTypeSO::ChargeThroughClaim || chargeThroughType == METInvoiceTypeSO::CrossDockClaim)
        {
            salesInvoiceHeaderFooterTmp.METFees = 0.01 * salesInvoiceTmp.LineAmountInclTax;
        }
        else
        {
            salesInvoiceHeaderFooterTmp.METFees = abs(markupTransHeaderFees.CalculatedAmount);
        }
        //GST Invoice header
        TaxTrans taxTransHeaderGST;

        select sum(SourceRegulateAmountCur) from taxTransHeaderGST
            where taxTransHeaderGST.Voucher == _custInvoiceJour.LedgerVoucher
            && taxTransHeaderGST.InventTransId == ''
            && taxTransHeaderGST.TransDate == _custInvoiceJour.InvoiceDate;

        salesInvoiceHeaderFooterTmp.METGSTActual = abs(taxTransHeaderGST.SourceRegulateAmountCur);

        salesInvoiceHeaderFooterTmp.METFeesTotal = salesInvoiceHeaderFooterTmp.METFees + salesInvoiceHeaderFooterTmp.METGSTActual;
    }

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    /// <param name = "_taxSpec">_taxSpec</param>
    /// <param name = "_custPaymSchedLine">_custPaymSchedLine</param>
    /// <param name = "_prepaymentCustTrans">_prepaymentCustTrans</param>
    /// <param name = "_prepaymentTaxTrans">_prepaymentTaxTrans</param>
    protected void populateSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour,
                                            CustInvoiceTrans _custInvoiceTrans,
                                            TaxSpec _taxSpec,
                                            CustPaymSchedLine _custPaymSchedLine,
                                            CustTrans _prepaymentCustTrans,
                                            TaxTrans _prepaymentTaxTrans)
    {
        next populateSalesInvoiceTmp(_custInvoiceJour,
                                    _custInvoiceTrans,
                                    _taxSpec,
                                    _custPaymSchedLine,
                                    _prepaymentCustTrans,
                                    _prepaymentTaxTrans);
        
        //MPJ_31513 Invoicing Design Begin

        SalesLine salesLine = SalesLine::findInventTransId(_custInvoiceTrans.InventTransId);
        SalesTable salestableloc = SalesTable::find(salesLine.SalesId);
        TaxTrans metTaxTransStd;
        METIndustryKey parentIndustryKey = METIndustryKeyTable::find(METCustTable::find(_custInvoiceJour.salestable().CustAccount).IndustryKey).ParentIndustryKey;
        if ((parentIndustryKey == METConstants::MFG || parentIndustryKey == METConstants::CSDCustName) && salesLine.METCWActualWeight > 0)
        {
            salesInvoiceTmp.qty = _custInvoiceTrans.PdsCWQty;
        }

        METSalesLinePriceComponent  metSalesLinePriceComponentloc;
        
        select sum(value) from metSalesLinePriceComponentloc
            where metSalesLinePriceComponentloc.Component == METConstants::DeliveryFee && metSalesLinePriceComponentloc.InventTransId == salesLine.inventtransid;

        salesInvoiceTmp.METDeliveryFee          =   metSalesLinePriceComponentloc.Value;
        salesInvoiceTmp.METDeliveryFeeExt       =   metSalesLinePriceComponentloc.Value * _custInvoiceTrans.Qty;

        //Bug 405074 - CR - UAT - DEMAND - LIQUOR - Validate that PE Pricing - Raise a manual order in PE as a Bonus Stock Override - did not invoice correctly - start.
        salesInvoiceTmp.METINDS                 =   salesLine.getSalesLineInvoiceIndicator(true);
        //Bug 405074 - CR - UAT - DEMAND - LIQUOR - Validate that PE Pricing - Raise a manual order in PE as a Bonus Stock Override - did not invoice correctly - end.

        select firstonly TaxValue from metTaxTransStd
            where metTaxTransStd.InventTransId == _custInvoiceTrans.InventTransId;
        
        salesInvoiceTmp.METTaxPercent   = metTaxTransStd.TaxValue;
        
        MarkupTrans metMarkupTransStd   = MarkupTrans::findValue(_custInvoiceTrans.TableId, _custInvoiceTrans.RecId);
        salesInvoiceTmp.MarkupCode      = metMarkupTransStd.MarkupCode;
        salesInvoiceTmp.MarkupAmount    = metMarkupTransStd.CalculatedAmount;

        METInventItemOrderSetup metInventItemOrderSetup;

        select firstonly ItemType from metInventItemOrderSetup
            where metInventItemOrderSetup.ItemId    == _custInvoiceTrans.ItemId
                && metInventItemOrderSetup.SiteId   == _custInvoiceTrans.inventSiteId();

        //salesInvoiceTmp.METCAT                          = metInventItemOrderSetup.ItemType; //added new logic cb272
        salesInvoiceTmp.METAlcoholCategory = METItemType::find(metInventItemOrderSetup.ItemType).Description;
        
        salesInvoiceTmp.METRetailAmount = salesInvoiceTmp.LineAmount;

        select TaxCode, TaxGroup, sum(SourceTaxAmountCur) from metTaxTransStd
        group by TaxCode, TaxGroup
            where metTaxTransStd.InventTransId  == _custInvoiceTrans.InventTransId
                && metTaxTransStd.TaxCode       == _custInvoiceTrans.TaxItemGroup
                && metTaxTransStd.TaxGroup      == _custInvoiceTrans.TaxGroup;
        
        if(metTaxTransStd.TaxGroup == METConstants::GST)
        {
            salesInvoiceTmp.METGSTValue = abs(metTaxTransStd.SourceTaxAmountCur);

            if(salestableloc.SalesType == SalesType::ReturnItem)
            {
                salesInvoiceTmp.METGSTValue = -1 * abs(metTaxTransStd.SourceTaxAmountCur);
            }
            salesInvoiceTmp.METGST = salesInvoiceTmp.METGSTValue != 0 ? METConstants::Y : METConstants::N;
        }
        else
        {
            salesInvoiceTmp.METGST      = 'N';
        }

        select sum(SourceTaxAmountCur) from metTaxTransStd
            where metTaxTransStd.InventTransId == _custInvoiceTrans.InventTransId
                && (metTaxTransStd.TaxCode == METConstants::GST || metTaxTransStd.TaxCode == METConstants::WEG);
          
        salesInvoiceTmp.METGSTTotal = abs(metTaxTransStd.SourceTaxAmountCur);
        
        if(salestableloc.SalesType == SalesType::ReturnItem)
        {
            salesInvoiceTmp.METGSTTotal = -1 * abs(metTaxTransStd.SourceTaxAmountCur);
        }
        if (salesInvoiceTmp.METGSTTotal)
        {
            salesInvoiceTmp.METGST      = 'Y';
        }

        boolean isALMReport;
        if (METSalesOrderTypes::find(_custInvoiceJour.salestable().METSalesOrderType).SalesInvoiceReportDesignName == METConstants::ALMDirectsCTInvoice)
        {
            isALMReport = NoYes::Yes;
        }

        select TaxCode, sum(SourceTaxAmountCur) from metTaxTransStd
            group by taxCode
            where metTaxTransStd.InventTransId  == _custInvoiceTrans.InventTransId && metTaxTransStd.TaxCode == METConstants::WET;
        
        if(metTaxTransStd.TaxCode == METConstants::WET)
        {
            salesInvoiceTmp.METWETValue = abs(metTaxTransStd.SourceTaxAmountCur);
            salesInvoiceTmp.METWET = (salesInvoiceTmp.METWETValue != 0) ? 'Y' : 'N';

            if (isALMReport)
            {
                salesInvoiceTmp.METGST = salesInvoiceTmp.METWETValue != 0 ? METConstants::Y : METConstants::N;
            }
        }
        else
        {
            salesInvoiceTmp.METWET      = 'N';
        }

        
        salesInvoiceTmp.METWholesaleListPrice = _custInvoiceTrans.SalesPrice;
        
        if(_custInvoiceTrans.SalesUnit == 'ea')
        {
            salesInvoiceTmp.METPackQty      =   1;
            salesInvoiceTmp.METSuppliedQty  =   _custInvoiceTrans.METPickedBrokenCases; 
        }
        else
        {
            salesInvoiceTmp.METPackQty      =  UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit), UnitOfMeasure::unitOfMeasureIdBySymbol('ea'), NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No);
            salesInvoiceTmp.METSuppliedQty  =   _custInvoiceTrans.METPickedCases;
        }

        salesInvoiceTmp.METAlcLitres        = any2Real(_custInvoiceTrans.METLitres);//get litres value

        salesInvoiceTmp.METSize             = METInventTable::find(_custInvoiceTrans.ItemId).ItemSize;
        
        // salesInvoiceTmp.METCost             = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::No);
        //Base cost custom change for ALM reports.
        real linecharges;
        real uomConversion = 1.0;

        if (parentIndustryKey == METConstants::ALMOrderType)// and report name alm
        {
            salesInvoiceTmp.METCost = this.getconversionValue(_custInvoiceTrans,salesLine);
            // only for ALM.
            linecharges = this.getLinecharges(_custInvoiceTrans,salesLine);
        
            

            // Use your new helper method if the unit is 'ea'
            if (_custInvoiceTrans.SalesUnit == METConstants::unitEach)
            {
                uomConversion = this.getconversionValueforEA(_custInvoiceTrans);
            }
            // Sum WET, Delivery Fee, and GST first, then apply Qty division and UoM conversion
            real combinedCharges = salesInvoiceTmp.METWETValue + salesInvoiceTmp.METGSTTotal;//linecharges replaced with deliverycharges
            real convertedCharges = (combinedCharges / _custInvoiceTrans.Qty) * uomConversion; 
            // add broken fees without conversion
            select sum(value) from metSalesLinePriceComponentloc
                where metSalesLinePriceComponentloc.Component == METConstants::brokenCaseFee 
                && metSalesLinePriceComponentloc.InventTransId == salesLine.inventtransid;

            // Use your new helper method if the unit is 'ea'
            if (_custInvoiceTrans.SalesUnit == METConstants::unitEach)
            {
                // Final Case Cost
                salesInvoiceTmp.metcaseCost = salesInvoiceTmp.METCost + (combinedCharges + metSalesLinePriceComponentloc.Value)*uomConversion;
            }
            else
            {
                salesInvoiceTmp.metcaseCost = salesInvoiceTmp.METCost + salesInvoiceTmp.METDeliveryFee + convertedCharges + metSalesLinePriceComponentloc.Value;
            }
                      
            //Base Cost + WET+delivery fee+ GST
            //salesInvoiceTmp.metcaseCost = salesInvoiceTmp.METCost + salesInvoiceTmp.metwetvalue + linecharges + salesInvoiceTmp.METGSTTotal;
        }
        else
        {
           // salesInvoiceTmp.METCost = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::No) * _custInvoiceTrans.qty;
           salesInvoiceTmp.METCost = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::No, salesLine);
        }
        

        salesInvoiceTmp.METRebatesFees      = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::Yes) * _custInvoiceTrans.qty;
        if (parentIndustryKey == METConstants::MFG || parentIndustryKey == METConstants::CSDCustName)
        {
            if (salestableloc.SalesType == SalesType::ReturnItem)
            {
                salesInvoiceTmp.METRebatesFees = -1* abs(salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::Yes) * _custInvoiceTrans.qty);

                LineAmount lineAmount       = abs(_custInvoiceTrans.LineAmount) + salesInvoiceTmp.METRebatesFees;
                LineAmount lineAmtInclTax   = lineAmount + abs(salesInvoiceTmp.metgstvalue);

                salesInvoiceTmp.lineAmount          = -1 * (abs(_custInvoiceTrans.LineAmount) + salesInvoiceTmp.METRebatesFees);
                salesInvoiceTmp.LineAmountInclTax   = -1 * lineAmtInclTax;
                //salesInvoiceTmp.METLucInclGST       = (lineAmtInclTax/_custInvoiceTrans.Qty)/salesInvoiceTmp.METPackQty;
                salesInvoiceTmp.METLucExclGST       = -1 * abs(_custInvoiceTrans.LineAmount + salesInvoiceTmp.METRebatesFees);
                salesInvoiceTmp.METLucInclGST       = -1 * abs(salesInvoiceTmp.METLucExclGST + salesInvoiceTmp.metgstvalue);
            }
            else
            {
                salesInvoiceTmp.lineAmount          = _custInvoiceTrans.LineAmount + salesInvoiceTmp.METRebatesFees;
                salesInvoiceTmp.LineAmountInclTax   = salesInvoiceTmp.LineAmount + salesInvoiceTmp.metgstvalue;

                if (_custInvoiceTrans.Qty && salesInvoiceTmp.METPackQty)
                {
                    salesInvoiceTmp.METLucInclGST   = (salesInvoiceTmp.LineAmountInclTax/_custInvoiceTrans.Qty)/salesInvoiceTmp.METPackQty;
                    salesInvoiceTmp.METLucExclGST   = (salesInvoiceTmp.LineAmount/_custInvoiceTrans.Qty)/salesInvoiceTmp.METPackQty;
                }
                else
                {
                    salesInvoiceTmp.METLucInclGST   = 0;
                    salesInvoiceTmp.METLucExclGST   = 0;
                }
            }
        }

        else
        {
            salesInvoiceTmp.LineAmountInclTax   = salesInvoiceTmp.LineAmount + salesInvoiceTmp.TaxAmount;
        }
        // Bug 285174 added for GST exempted items
        if(InventTable::find(_custInvoiceTrans.ItemId).metGetProductAttributeforCategory(METConstants::ConsumerGSTExempt) == "Yes")
        {
            salesInvoiceTmp.METGSTExempt = salesInvoiceTmp.LineAmountInclTax;
        }

        if(!salesInvoiceTmp.TaxAmount && !metMarkupTransStd.TaxAmount)
        {
            salesInvoiceTmp.METAmountTaxExempt = _custInvoiceTrans.LineAmount;//also used in CT invoice reort
        }
        /*
        if(_custInvoiceTrans.Qty && salesInvoiceTmp.METPackQty)
        {
            salesInvoiceTmp.METLucInclGST = (salesInvoiceTmp.LineAmountInclTax/_custInvoiceTrans.Qty)/salesInvoiceTmp.METPackQty;
        }
        else
        {
            salesInvoiceTmp.METLucInclGST = 0;
        }*/

        salesInvoiceTmp.Name                = EcoResProductTranslation::getNameOrDefaultName(EcoResProduct::findByProductNumber( _custInvoiceTrans.ItemId).RecId, SysUserInfo::find(curUserId()).Language);
        
        if (parentIndustryKey == METConstants::ALMOrderType)
        {
            //real totalPriceExclGST = salesInvoiceTmp.METCost + salesInvoiceTmp.metwetvalue + linecharges;
            // salesInvoiceTmp.METLucInclGST = totalPriceExclGST + salesInvoiceTmp.METGSTTotal ;
            // new logic 09032026

            if (_custInvoiceTrans.SalesUnit == METConstants::unitEach && uomConversion != 0)
            {
                salesInvoiceTmp.METLucInclGST = (salesInvoiceTmp.metcaseCost * salesInvoiceTmp.Qty)/ uomConversion;
                //salesInvoiceTmp.METLucInclGST = (salesInvoiceTmp.metcaseCost * salesLine.SalesQty)/ uomConversion;
            }
            else
            {
                salesInvoiceTmp.METLucInclGST = salesInvoiceTmp.metcaseCost * salesInvoiceTmp.Qty;//salesLine.SalesQty;
            }
            // change value to -ve for return type
            if (salestableloc.SalesType == SalesType::ReturnItem)
            {
                METSalesLinePriceComponentTmp priceComponentTmp;

                priceComponentTmp.linkPhysicalTableInstance(METSalesPriceComponents::construct(salesLine.salesTable().SalesType).insertTmp(salesLine));

                select firstonly priceComponentTmp
                    where priceComponentTmp.PriceComponent == METPriceComponent::NetAmount;

                select sum(value) from metSalesLinePriceComponentloc
                    where metSalesLinePriceComponentloc.Component == METConstants::brokenCaseFee && metSalesLinePriceComponentloc.InventTransId == salesLine.inventtransid;

                if (priceComponentTmp.RecId)
                {
                    salesInvoiceTmp.METLucInclGST = -1 * abs(priceComponentTmp.ExtValue + salesInvoiceTmp.METWETValue + salesInvoiceTmp.METDeliveryFee + salesInvoiceTmp.METGSTTotal + metSalesLinePriceComponentloc.Value);

                    salesInvoiceTmp.METLucExclGST = -1 * abs(salesInvoiceTmp.METLucInclGST - salesInvoiceTmp.METGSTTotal);
                }

                //salesInvoiceTmp.METLucInclGST = -1 * abs(salesInvoiceTmp.METLucInclGST);
            }
             
            if(salesInvoiceTmp.Qty && salesInvoiceTmp.METPackQty)
            {
                real totalPriceExclGSTForLUC = salesInvoiceTmp.METLucInclGST - salesInvoiceTmp.METGSTTotal;
                
                if (!salesInvoiceTmp.METLucExclGST)
                {
                    salesInvoiceTmp.METLucExclGST = (totalPriceExclGSTForLUC / salesInvoiceTmp.Qty) / salesInvoiceTmp.METPackQty;
                    // salesInvoiceTmp.METLucExclGST       = (totalPriceExclGST/salesInvoiceTmp.Qty)/salesInvoiceTmp.METPackQty;

                    if (salestableloc.SalesType == SalesType::ReturnItem)
                    {
                        salesInvoiceTmp.METLucExclGST = -1 * abs(salesInvoiceTmp.METLucExclGST);
                    }
                }
            }
            else
            {
                salesInvoiceTmp.METLucExclGST       = 0;
            }
        }

        salesInvoiceTmp.METSupplierInvoiceAmtInclGST    = salesInvoiceTmp.LineAmountInclTax;//salesInvoiceTmp.METGSTValue + _custInvoiceTrans.lineamount;
        
        if (isALMReport)
        {
            // if GST value is blank then pass the WEG value.
            select sum(SourceTaxAmountCur) from metTaxTransStd
                where metTaxTransStd.InventTransId == _custInvoiceTrans.InventTransId && (metTaxTransStd.TaxCode == METConstants::WEG || metTaxTransStd.TaxCode == METConstants::GST);
            salesInvoiceTmp.METSupplierInvoiceGST =  abs(metTaxTransStd.SourceTaxAmountCur);
        }

        //Bug 405074 - CR - UAT - DEMAND - LIQUOR - Validate that PE Pricing - Raise a manual order in PE as a Bonus Stock Override - did not invoice correctly - start.
        if (salesInvoiceTmp.METINDS == METConstants::BonusInd)
        {
            salesInvoiceTmp.METCaseCost = 0;
            salesInvoiceTmp.METLucInclGST = (salestableloc.SalesType == SalesType::ReturnItem) ? salesInvoiceTmp.METLucInclGST : salesInvoiceTmp.METDeliveryFee;
            salesInvoiceTmp.METLucExclGST = 0;
        }
        //Bug 405074 - CR - UAT - DEMAND - LIQUOR - Validate that PE Pricing - Raise a manual order in PE as a Bonus Stock Override - did not invoice correctly - end.

    }

    /// <summary>
    /// getconversion
    /// </summary>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    /// <param name = "_salesline">_salesline</param>
    /// <returns>Amount</returns>
    public Amount getconversionValue(CustInvoiceTrans _custInvoiceTrans, SalesLine _salesline)
    {
        InventItemSalesSetup inventItemSalesSetup;
        METComponentCode metComponentCode;
        Inventdim inventdim;
        Real convertedValue = 1, calculatedBaseAmt;
        METSalesLinePriceComponent metSalesLinePriceComponentAct, metSalesLinePriceComponentFees, metSalesLinePriceComponentDisc;
        InventTransId targetInventTransId;

        // Determine the correct InventTransId based on SalesType
        if (_salesline.SalesType == SalesType::ReturnItem)
        {
            // Use your existing custom utility to fetch the original order's Lot ID
            targetInventTransId = this.getInventTransID(_salesline);
        }
        else
        {
            targetInventTransId = _custInvoiceTrans.InventTransId;
        }

        select METSalesUnit from inventItemSalesSetup
         exists join inventdim where inventdim.inventdimid == inventItemSalesSetup.INVENTDIMID
             && inventItemSalesSetup.itemid == _custInvoiceTrans.ItemId
             && inventdim.InventSiteId == _custInvoiceTrans.inventSiteId();
         
        // BasePrice cost
        select InventTransId, sum(Value) from metSalesLinePriceComponentAct
                group by InventTransId
                join metComponentCode
                    where metSalesLinePriceComponentAct.Component == metComponentCode.Component
                    && metSalesLinePriceComponentAct.InventTransId == targetInventTransId
            && metComponentCode.PriceComponent == METPriceComponent::BasePrice;

        // Margins
        select InventTransId, sum(Value) from metSalesLinePriceComponentFees
            group by InventTransId
                join metComponentCode
                    where metSalesLinePriceComponentFees.Component == metComponentCode.Component
                        && metSalesLinePriceComponentFees.InventTransId == targetInventTransId
                        && metComponentCode.PriceComponent == METPriceComponent::Margins;

        // discounts
        select InventTransId, sum(Value) from metSalesLinePriceComponentDisc
            group by InventTransId
                join metComponentCode
                    where metSalesLinePriceComponentDisc.Component == metComponentCode.Component
                        && metSalesLinePriceComponentDisc.InventTransId == targetInventTransId
                        && metComponentCode.PriceComponent == METPriceComponent::Discounts;
        
        RecId UnitOfMeasureRecId = UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit);

        if (_custInvoiceTrans.SalesUnit == 'ea' && UnitOfMeasureConverter::canBeConverted(UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemSalesSetup.METSalesUnit), UnitOfMeasureRecId, InventTable::itemProduct(_custInvoiceTrans.ItemId)))
        {
            convertedValue =  UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemSalesSetup.METSalesUnit), UnitOfMeasureRecId, NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No);
        }

        calculatedBaseAmt = convertedValue * (metSalesLinePriceComponentAct.Value + metSalesLinePriceComponentFees.Value - metSalesLinePriceComponentDisc.Value);
      
        return calculatedBaseAmt;
    }

    /// <summary>
    /// get invent transid from original sales order
    /// </summary>
    /// <param name = "_salesLine">SalesLine</param>
    /// <returns>InventTransId</returns>
    public InventTransId getInventTransID(SalesLine _salesLine)
    {
        SalesLine     selSalesLine;
        METSalesTable metSalesTable = METSalesTable::findBySalesId(_salesLine.SalesId);
        SalesId       originalSalesId;

        // Early exit if the custom table record or OriginalInvoice reference is missing
        if (!metSalesTable || !metSalesTable.OriginalInvoice)
        {
            return '';
        }

        // Replicate the reliable mapping logic from METSalesPriceComponents_Return
        SalesTable salesTable = SalesTable::find(metSalesTable.OriginalInvoice);

        if (salesTable.RecId)
        {
            // The OriginalInvoice field contains the actual SalesId
            originalSalesId = metSalesTable.OriginalInvoice;
        }
        else
        {
            // The OriginalInvoice field contains the InvoiceId, so we must trace it back
            CustInvoiceJour custInvoiceJour;

            select firstOnly SalesId from custInvoiceJour
                order by InvoiceDate desc
                where custInvoiceJour.InvoiceId == metSalesTable.OriginalInvoice
                exists join salesTable
                    where custInvoiceJour.InvoiceAccount == salesTable.CustAccount &&
                          salesTable.RecId == metSalesTable.SalesTable;

            originalSalesId = custInvoiceJour.SalesId;
        }

        // Fetch the corresponding original InventTransId based on the resolved SalesId
        if (originalSalesId)
        {
            select firstonly InventTransId from selSalesLine
                where selSalesLine.SalesId == originalSalesId
                   && selSalesLine.ItemId == _salesLine.ItemId;

            return selSalesLine.InventTransId;
        }

        return '';
    }

    /// <summary>
    /// get conversion value for EA unit
    /// </summary>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    /// <returnsAmount></returns>
    public Amount getconversionValueforEA(CustInvoiceTrans _custInvoiceTrans)
    {
        InventItemSalesSetup inventItemSalesSetup;
        Inventdim inventdim;
        Real convertedValue = 1;

        select METSalesUnit from inventItemSalesSetup
         exists join inventdim where inventdim.inventdimid == inventItemSalesSetup.INVENTDIMID
             && inventItemSalesSetup.itemid == _custInvoiceTrans.ItemId && inventdim.InventSiteId == _custInvoiceTrans.inventSiteId();
        
        RecId UnitOfMeasureRecId = UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit);

        if (_custInvoiceTrans.SalesUnit == METConstants::unitEach && UnitOfMeasureConverter::canBeConverted(UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemSalesSetup.METSalesUnit), UnitOfMeasureRecId, InventTable::itemProduct(_custInvoiceTrans.ItemId)))
        {
            convertedValue =  UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemSalesSetup.METSalesUnit), UnitOfMeasureRecId, NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No);
        }
         
        return convertedValue;
    }

    public Amount getLinecharges(CustInvoiceTrans _custInvoiceTrans ,SalesLine _salesline)
    {
        METComponentCode metComponentCode;
        METSalesLinePriceComponent metSalesLinePriceComponent;
        real amount;

        while select metSalesLinePriceComponent
            where metSalesLinePriceComponent.InventTransId == _custInvoiceTrans.InventTransId
        {
            select firstonly metComponentCode
                where metComponentCode.Component == metSalesLinePriceComponent.Component && metComponentCode.IncludeInRebatesOrFees == NoYes::Yes
                && metComponentCode.Component != METConstants::excise && metComponentCode.Component != METConstants::pickFee; // added to remove incosistent data issue
            
            if (metComponentCode.PriceComponent == METPriceComponent::LineCharges)
            {
                amount += metSalesLinePriceComponent.Value;
            }
        }
        return amount;//multiplied for ext value
    }
